export function splitSpansIntoRows(spans: HighlightSpan[]): string[][] {
  const rows: string[][] = [];
  let currentRow: string[] = [];
  let openScope: string | null = null;

  for (const span of spans) {
    const parts = span.text.split('\n');

    for (let i = 0; i < parts.length; i++) {
      const part = parts[i];

      if (i > 0) {
        // Flush previous row.
        rows.push(currentRow);
        currentRow = [];
      }

      if (i < parts.length - 1) {
        // Not the last part — a newline follows.
        if (part) {
          currentRow.push({ text: part, scope: span.scope });
        }
        // Scope carries across the line break.
        if (span.scope) openScope = span.scope;
      } else {
        // Last part.
        if (part) {
          currentRow.push({ text: part, scope: openScope || span.scope || null });
        }
        // Reset scope tracking for next row.
        openScope = null;
      }
    }
  }

  if (currentRow.length > 0) rows.push(currentRow);
  return rows;
}
```

