export function highlightSpans(code: string, language: string): HighlightSpan[] {
  const lang = resolveLanguage(language);
  if (!code.trim() || chalk.level === 0 || lang === 'plaintext') return [{ text: code }];
  try {
    const emitter = new ScopeEmitter();
    const result = hljs.highlight(code, { language: lang, ignoreIllegals: true, __emitter: emitter });
